package estate.svc;

import estate.api.Context;
import estate.api.Service;
import estate.api.ServiceException;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;

/** Ledger: persistent postings with idempotent posting by requestId. */
public class Main implements Service {
    private Context ctx;
    private Connection db;

    @Override
    public void start(Context c) throws Exception {
        this.ctx = c;
        this.db = c.db();
        try (Statement s = db.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS schema_version(v INT NOT NULL)");
            int v = 0;
            try (ResultSet rs = s.executeQuery("SELECT COALESCE(MAX(v),0) FROM schema_version")) {
                if (rs.next()) v = rs.getInt(1);
            }
            if (v < 1) {
                s.execute("CREATE TABLE postings(id BIGINT AUTO_INCREMENT PRIMARY KEY, account VARCHAR(40) NOT NULL, "
                        + "amount DECIMAL(18,2) NOT NULL, request_id VARCHAR(80) NOT NULL UNIQUE, ts BIGINT NOT NULL)");
                s.execute("INSERT INTO schema_version(v) VALUES (1)");
            }
        }
    }

    @Override
    public Map<String, String> handle(String op, Map<String, String> req) throws ServiceException {
        try {
            switch (op) {
                case "health": return health();
                case "post": return post(req);
                case "balance": return balance(req);
                case "postings": return postings(req);
                default: throw new ServiceException("error", "unknown op " + op);
            }
        } catch (ServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new ServiceException("error", String.valueOf(e.getMessage()));
        }
    }

    private Map<String, String> health() throws Exception {
        try (Statement s = db.createStatement(); ResultSet rs = s.executeQuery("SELECT COALESCE(SUM(amount),0) FROM postings")) {
            rs.next();
        }
        return Map.of("status", "UP");
    }

    private Map<String, String> post(Map<String, String> req) throws Exception {
        String account = req.get("account");
        BigDecimal amount = new BigDecimal(req.get("amount")).setScale(2);
        String requestId = req.get("requestId");
        try (PreparedStatement q = db.prepareStatement("SELECT id FROM postings WHERE request_id = ?")) {
            q.setString(1, requestId);
            try (ResultSet rs = q.executeQuery()) {
                if (rs.next()) return Map.of("id", String.valueOf(rs.getLong(1)), "dup", "true");
            }
        }
        long id;
        try (PreparedStatement ins = db.prepareStatement(
                "INSERT INTO postings(account, amount, request_id, ts) VALUES (?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) {
            ins.setString(1, account);
            ins.setBigDecimal(2, amount);
            ins.setString(3, requestId);
            ins.setLong(4, ctx.now());
            ins.executeUpdate();
            try (ResultSet k = ins.getGeneratedKeys()) { k.next(); id = k.getLong(1); }
        }
        Map<String, String> ev = new HashMap<>();
        ev.put("account", account);
        ev.put("amount", amount.toPlainString());
        ev.put("requestId", requestId);
        ctx.publish("payment.posted", ev);
        return Map.of("id", String.valueOf(id), "dup", "false");
    }

    private Map<String, String> balance(Map<String, String> req) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT COALESCE(SUM(amount),0) FROM postings WHERE account = ?")) {
            q.setString(1, req.get("account"));
            try (ResultSet rs = q.executeQuery()) {
                rs.next();
                return Map.of("balance", rs.getBigDecimal(1).setScale(2).toPlainString());
            }
        }
    }

    private Map<String, String> postings(Map<String, String> req) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM postings WHERE account = ?")) {
            q.setString(1, req.get("account"));
            try (ResultSet rs = q.executeQuery()) {
                rs.next();
                return Map.of("count", String.valueOf(rs.getLong(1)), "total", rs.getBigDecimal(2).setScale(2).toPlainString());
            }
        }
    }
}
package estate.svc;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    private Main start(FakeContext c) throws Exception {
        Main m = new Main();
        m.start(c);
        return m;
    }

    @Test
    void postStoresAndPublishes() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        Map<String, String> r = m.handle("post", Map.of("account", "a1", "amount", "12.5", "requestId", "r1"));
        assertEquals("false", r.get("dup"));
        assertEquals("12.50", m.handle("balance", Map.of("account", "a1")).get("balance"));
        assertEquals("payment.posted", c.published.get(0));
        assertEquals("12.50", c.events.get(0).get("amount"));
    }

    @Test
    void sameRequestIdPostsOnce() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        m.handle("post", Map.of("account", "a1", "amount", "5.00", "requestId", "r1"));
        Map<String, String> r = m.handle("post", Map.of("account", "a1", "amount", "5.00", "requestId", "r1"));
        assertEquals("true", r.get("dup"));
        assertEquals("1", m.handle("postings", Map.of("account", "a1")).get("count"));
        assertEquals(1, c.events.size());
    }

    @Test
    void healthIsUp() throws Exception {
        assertEquals("UP", start(new FakeContext()).handle("health", Map.of()).get("status"));
    }
}
package estate.api;

import java.sql.Connection;
import java.util.Map;

/** What the platform gives an instance. The database is shared by every instance and every version of the service. */
public interface Context {
    Connection db();

    /** Synchronous call to another service. Throws ServiceException with code "timeout", "unavailable" or "error". */
    Map<String, String> call(String service, String op, Map<String, String> request) throws ServiceException;

    /** Publish an event; consumers receive it a few ticks later. */
    void publish(String topic, Map<String, String> event);

    /** Platform clock (ticks). */
    long now();
}
package estate.api;

import java.util.Map;

/** A deployable service. One instance of the implementing class runs per deployed instance of the service. */
public interface Service {
    /** Called once when an instance starts. Run your schema migrations here. */
    void start(Context ctx) throws Exception;

    /** Handle a synchronous request. `op` and the maps are the service's published contract. */
    Map<String, String> handle(String op, Map<String, String> req) throws ServiceException;

    /** Handle an asynchronous event from a topic this service subscribes to. */
    default void onEvent(String topic, Map<String, String> event) throws Exception {}
}
package estate.api;

public class ServiceException extends Exception {
    public final String code;

    public ServiceException(String code, String message) {
        super(message);
        this.code = code;
    }
}
package estate.svc;

import estate.api.Context;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

/** Test double for the platform: in-memory H2, stubbed calls, recorded events. */
public class FakeContext implements Context {
    private static final AtomicInteger N = new AtomicInteger();

    public interface Stub { Map<String, String> apply(Map<String, String> req) throws ServiceException; }

    public final Map<String, Stub> stubs = new HashMap<>();
    public final List<String> published = new ArrayList<>();
    public final List<Map<String, String>> events = new ArrayList<>();
    public long tick = 0;
    private final Connection db;

    public FakeContext() {
        try {
            db = DriverManager.getConnection("jdbc:h2:mem:test" + N.incrementAndGet() + ";DB_CLOSE_DELAY=-1");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public Connection db() { return db; }

    public Map<String, String> call(String service, String op, Map<String, String> request) throws ServiceException {
        Stub s = stubs.get(service + "." + op);
        if (s == null) throw new ServiceException("unavailable", "no stub for " + service + "." + op);
        return s.apply(request);
    }

    public void publish(String topic, Map<String, String> event) { published.add(topic); events.add(event); }

    public long now() { return tick; }
}

